            gPathOuter = GetRoundedPath(outerRect, radiusTL, radiusTR, radiusBL, radiusBR);            using (var path = (GraphicsPath)gPathOuter.Clone()) {                // fill                using (var brush = new SolidBrush(fillColor)) {                    g.FillPath(brush, path);                }		//OR/*                g.SetClip(path);                g.FillRectangle(Brushes.Black, rc);                g.ResetClip();*/                // border                if (borderSize > 0) {                    using (var pen = new Pen(borderColor, borderSize)) {                        if (borderType != OutlineType.Plná) {                            pen.DashStyle = Translate.GetDashStyle(borderType);                        }                        g.DrawPath(pen, path);                    }                }            }